fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since a and b have the same length, we can safely zip their iterators.
    // into_iter() moves out the u8 values, and we XOR them pairwise.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x ^ y)
     .collect()
}

